    '<div><span>Hace más que no salen</span><p>' + old.map(function (r) { return chipEp(r, r.last); }).join("") + "</p></div>" +
    '<div><span>Aún no han salido</span><p>' + (never.length ? never.map(function (r) { return chipEp(r); }).join("") : "<em>Ninguno</em>") + "</p></div></div>";
